#!/usr/bin/env node
/**
 * Build lib/index.js from src/index.js, and verify it when it already exists.
 *
 * The generated file is one comment banner plus the source verbatim - no bundling, no transform.
 * That keeps the artifact reviewable, and it is why this script is also a drift check: run it in CI
 * and a lib/ that no longer matches src/ fails the build instead of being discovered by a user.
 *
 * The banner is deterministic: it carries the package version and nothing machine-specific, so a
 * build on one machine matches a build on another.
 *
 * Usage: node scripts/build.mjs          generate (or refresh) lib/index.js
 *        node scripts/build.mjs --check  fail if lib/index.js is stale
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const TARGET = path.join(ROOT, 'lib', 'index.js');

const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8'));
const source = fs.readFileSync(path.join(ROOT, 'src', 'index.js'), 'utf8');

const banner = [
  '// Generated by scripts/build.mjs from src/index.js - edit the source, then run npm run build.',
  `// ${pkg.name} ${pkg.version}`,
  '// SPDX-License-Identifier: LicenseRef-CZGD-PL-1.0',
  '',
].join('\n');
const built = banner + source;

const checkOnly = process.argv.includes('--check');
if (checkOnly) {
  const current = fs.existsSync(TARGET) ? fs.readFileSync(TARGET, 'utf8') : '';
  if (current === built) {
    console.log(`build: lib/index.js matches src/index.js (${built.length} bytes, ${pkg.name} ${pkg.version})`);
    process.exit(0);
  }
  console.error('build: lib/index.js is stale - run `npm run build` and commit the result');
  process.exit(1);
}

fs.mkdirSync(path.dirname(TARGET), { recursive: true });
fs.writeFileSync(TARGET, built, 'utf8');
console.log(`built lib/index.js (${built.length} bytes) from src/index.js (${source.length} bytes), ${pkg.name} ${pkg.version}`);
